// Mock of Apple's push service — the only mock in the integration suite.
//
// A real HTTP/2 + TLS server (the app's apns.ts speaks http2 over TLS), with a
// throwaway self-signed cert generated by the openssl CLI into a temp dir at
// start and deleted on close. It records every request and answers 200, or 410
// (Unregistered) for tokens marked gone() — exactly what the app prunes on.
import http2 from "node:http2";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

export async function startMockApns() {
  const dir = mkdtempSync(join(tmpdir(), "mock-apns-"));
  const keyPath = join(dir, "key.pem");
  const certPath = join(dir, "cert.pem");
  execFileSync(
    "openssl",
    ["req", "-x509", "-newkey", "rsa:2048", "-nodes", "-days", "1", "-subj", "/CN=127.0.0.1",
      "-keyout", keyPath, "-out", certPath],
    { stdio: "ignore" }
  );

  const requests = [];
  const goneTokens = new Set();
  const server = http2.createSecureServer({
    key: readFileSync(keyPath),
    cert: readFileSync(certPath),
  });
  server.on("stream", (stream, headers) => {
    let body = "";
    stream.setEncoding("utf8");
    stream.on("data", (c) => (body += c));
    stream.on("end", () => {
      const path = String(headers[":path"]);
      const token = path.split("/").pop();
      const status = goneTokens.has(token) ? 410 : 200;
      requests.push({ method: headers[":method"], path, headers: { ...headers }, body, status });
      stream.respond({ ":status": status });
      stream.end(status === 410 ? JSON.stringify({ reason: "Unregistered" }) : "");
    });
  });
  const sessions = new Set();
  server.on("session", (s) => {
    sessions.add(s);
    s.on("close", () => sessions.delete(s));
  });
  server.on("sessionError", () => {});
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));

  return {
    port: server.address().port,
    requests,
    gone: (token) => goneTokens.add(token),
    clear: () => (requests.length = 0),
    close: () =>
      new Promise((resolve) => {
        server.close(() => resolve());
        sessions.forEach((s) => s.destroy());
        rmSync(dir, { recursive: true, force: true });
      }),
  };
}
